const raw = String($json.Brands ?? $json.brands ?? '').trim();
if (!raw) throw new Error('Brands list is empty');

const lines = raw.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
const rows = [];
const invalid = [];
const allowed = ['US','CA','AU','UK','NL','DE','FR'];

for (const line of lines) {
  const parts = line.split('|').map(s => s.trim());
  if (parts.length !== 3 || !parts[0] || !parts[1] || !parts[2]) {
    invalid.push(line);
    continue;
  }

  const [brand, domain, countryRaw] = parts;
  const country = countryRaw.toUpperCase() === 'GB' ? 'UK' : countryRaw.toUpperCase();

  if (!allowed.includes(country)) {
    invalid.push(line + ' [unsupported country]');
    continue;
  }

  rows.push({
    brand,
    website: /^https?:\/\//i.test(domain) ? domain : 'https://' + domain + '/',
    countries: [country]
  });
}

if (!rows.length) throw new Error('No valid rows. Use: Brand|domain|country');
if (invalid.length) throw new Error('Invalid rows: ' + invalid.join(' ; '));

const batchJson = JSON.stringify(rows);

return [{
  json: {
    brandCount: rows.length,
    brands: rows.map(x => ({
      brand: x.brand,
      domain: String(x.website)
        .replace(/^https?:\/\//i, '')
        .replace(/^www\./i, '')
        .replace(/\/.*$/, ''),
      country: x.countries[0]
    })),
    batchBase64: Buffer.from(batchJson, 'utf8').toString('base64')
  }
}];

const raw = $json.stdout;
if (!raw) throw new Error('Serper search returned empty stdout');

const data = JSON.parse(raw);
const sourceRows = $('Prepare Brand List').first().json.brands ?? [];
const expected = Number($('Prepare Brand List').first().json.brandCount ?? sourceRows.length);

if ((data.searches ?? []).length !== expected) {
  const got = (data.searches ?? []).map(x => x.brand).join(', ');
  const failed = (data.failures ?? []).map(x => `${x.brand} (${x.country}): ${x.error}`).join(' | ');
  throw new Error(`Expected ${expected} brand searches but got ${(data.searches ?? []).length}. Returned: ${got || 'none'}. Failures: ${failed || 'none'}`);
}

const domainMap = new Map(
  sourceRows.map(x => [String(x.brand).trim().toLowerCase(), x.domain])
);

return (data.searches ?? []).map(search => ({
  json: {
    brand: search.brand,
    domain: domainMap.get(String(search.brand).trim().toLowerCase()) ?? '',
    country: search.country,
    results: search.results ?? [],
    resultCount: (search.results ?? []).length,
    failures: (data.failures ?? []).filter(f => f.brand === search.brand && f.country === search.country)
  }
}));

return $input.all().map(({ json: item }) => {
const brand = item.brand;
const domain = item.domain;
const country = item.country;
const urls = (item.results ?? []).map(x => x.url).filter(Boolean).slice(0, 10);

const numbered = urls.map((u, i) => `${i + 1}. ${u}`).join('\n');

const prompt = `You are extracting coupon codes for ${brand} (${domain}) in ${country}.

IMPORTANT RULES:
- Use ONLY the supplied URLs below. Do not use Google or discover additional URLs.
- Audit every supplied URL.
- Extract up to the first 10 UNIQUE coupon/promo codes per URL.
- Preserve codes exactly as displayed, including unusual capitalization, punctuation, numbers, or symbols.
- If a coupon card has Show Code / Get Code / Reveal / View Code / Unlock / Copy Code, interact with it and inspect the resulting popup, modal, same-page reveal, clipboard value, or newly opened tab.
- If clicking redirects to the merchant, return to the coupon source and continue inspecting the coupon source itself.
- Ignore expired offers when clearly marked expired.
- For the official merchant website, only return an explicit coupon/promo code. A sale or percentage discount without an explicit code is NOT a coupon code.
- Check every supplied URL, including blocked or inaccessible sources; never invent codes.
- If a URL has zero verified codes, do not create a blank or fake coupon row.
- Do not test codes at checkout during Step 1. Step 3 handles official-site verification.

OUTPUT FORMAT: CSV ONLY, not JSON or Markdown.
Use exactly these columns in this order:
brand,country,source_url,coupon_code,status

Return one CSV row per ACTUAL verified coupon code (up to 10 unique codes per source URL).
For actual extracted codes set status to extracted.
If no codes are found, return the CSV header only.
Always inspect all supplied URLs, but do not add placeholder rows for no_code, blocked, skipped or error.
Use standard CSV quoting: fields containing commas, double quotes or line breaks must be double-quoted; double any quotes inside a quoted field.
Do not include explanations or code fences.

SUPPLIED URLS:
${numbered}`;

return { json: { ...item, couponPrompt: prompt } };
});

return (function buildDealPrompt($input){
 return $input.all().map(({json:item})=>{
  const brand=item.brand, domain=String(item.domain||"").trim().replace(/^https?:\/\//i,"").replace(/\/.*$/,""), country=item.country;
  const website="https://"+domain;
  const special = /(^|\.)ski-planet\.com$/i.test(domain.replace(/^www\./i,""))
    ? ["For Ski-Planet specifically, inspect these official pages before declaring no deals:",
       "https://www.ski-planet.com/fr/promo-ski.php",
       "https://www.ski-planet.com/fr/derniere-minute-ski.php?Order=promo",
       "https://www.ski-planet.com/fr/code-promo-ski.php",
       "These are research leads only: verify today's actual offers, prices, availability, dates and eligibility live."]
    : [];
  const prompt=[
    `Research current verified deals for ${brand} in ${country}, using ONLY the official website ${website} and its own www/local-language pages.`,
    "",
    "MANDATORY RESEARCH STEPS BEFORE RETURNING HEADER-ONLY CSV:",
    "1. Open the merchant homepage and inspect menu, nav, offer banners and footer for Sale, Promo, Discounts, Special Offers, Réductions, Dernière Minute, Bons Plans and local-language equivalents.",
    "2. Follow relevant official offer and listing pages; check real offer cards rather than relying only on the homepage.",
    "3. Adapt to business type: for travel/accommodation inspect discounted stays, booking dates, early booking, last-minute offers and packages; for services and telecom inspect promotional plans, reduced subscription fees and installation incentives; for retail inspect product discounts.",
    "4. Include only offers explicitly advertised on official pages with exact source URL, eligibility/booking dates where stated, and accurate promotional wording.",
    "5. Calculate lowest/highest sale prices and minimum/maximum discounts ONLY using original and sale prices from the SAME product, plan, stay, booking option AND dates. Advertised discount percentages can be stated as written when no original price is shown.",
    "6. Look for shipping/delivery discounts ONLY for merchants selling physical goods. Travel, services and digital-only subscriptions have no applicable shipping offer.",
    "7. Look for newsletter, SMS and new-customer incentives. A signup form or mailing list WITHOUT an explicit promotional benefit does NOT count as a newsletter deal.",
    "8. Officially advertised promo code offers may be reported in a sale row with the code and restrictions in deal_text, without claiming checkout validation.",
    ...special,
    "",
    "OUTPUT CSV ONLY, not JSON or Markdown, with these exact columns:",
    "brand,country,website,deal_type,source_url,deal_text,lowest_sale_price,highest_sale_price,currency,min_discount_percent,max_discount_percent",
    "Use deal_type sale, shipping, or newsletter. Use sale for travel-booking discounts and service plan promotions.",
    "One CSV row per clearly identified currently advertised offer. Include its exact official source URL.",
    "Leave numeric fields empty when not verified. Never combine unrelated products or booking dates to infer discounts.",
    "Do not create placeholder rows for unavailable deal categories.",
    "If no current deals can be verified after inspecting appropriate official pages, output only the header.",
    "CSV-quote fields containing commas, quotes or newlines; double internal quotes. No commentary or code fences."
  ].join("\n");
  return {json:{...item,dealPrompt:prompt}};
 });
})($input);
